mapper.select:
select od.* from order_detail od left join orders o on od.order_id = o.id 


        and od.number like concat('%',#{number},'%')


        and o.phone like concat('%',#{phone},'%')


        and o.user_id = #{userId}


        and o.status = #{status}


        and o.order_time >= #{beginTime}


        and o.order_time <= #{endTime}


order by o.order_time desc
